def solution(input_str):
    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    n = int(first_line[0])
    t = int(first_line[1])

    queries = []
    for i in range(1, t + 1):
        parts = lines[i].split()
        queries.append((int(parts[0]), int(parts[1])))

    if n == 0:
        return '\n'.join(['0'] * t)

    # We need to simulate the ant spreading process
    # Track ant positions in a dictionary
    # Use a set to track visited positions for optimization

    # Key insight: we need to simulate rounds of spreading
    # In each round, find all junctions with >= 4 ants and spread 4 ants

    # To handle large coordinates, we'll track all relevant positions

    ants = {(0, 0): n}

    # Limit simulation rounds - the process should terminate
    # Based on the problem pattern, ants spread in Manhattan distance layers

    ROUND_LIMIT = max(2 * n + 100, 200000)  # Sufficient rounds
    MAX_STEP = 10000  # Maximum coordinates to track from origin

    while ROUND_LIMIT > 0:
        ROUND_LIMIT -= 1

        # Find all positions that have >= 4 ants
        new_ants = {}

        for (x, y), count in ants.items():
            if count >= 4:
                remainder = count - 4

                # Add remainder back to this position
                new_ants[(x, y)] = new_ants.get((x, y), 0) + remainder

                # Spread 1 ant to each neighbor
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx, ny = x + dx, y + dy

                    # Skip if position is too far (optimization)
                    if min(abs(nx), abs(ny)) * 2 < ROUND_LIMIT * 4:
                        new_ants[(nx, ny)] = new_ants.get((nx, ny), 0) + 1

        ants = new_ants
        if not any(v >= 4 for v in ants.values()):
            break

    # Answer queries
    results = []
    for x, y in queries:
        # Check if we need to track positions far from origin
        if abs(x) > 1000000 or abs(y) > 1000000:
            # For very far positions, check if any ants reached there
            if (x, y) in ants:
                results.append(str(ants[(x, y)]))
            else:
                results.append('0')
        elif (x, y) in ants:
            results.append(str(ants[(x, y)]))
        else:
            results.append('0')

    return '\n'.join(results)

