def solve_dominate(l, r, p_val):
    """
    Compute probability whether in the asked interval l..r:
    - Start at l, must not lose (prob p[l-1])
    - Eventually win at r (must return and win)
    """
    if l == r:
        # Edge case: l = r, must loop back
        # Prob = p[l-1] * P(return to l from l+1) * p[l-1]
        left_limit = l - 2
        target = l - 1

        memo = {}
        def dp(pos):
            if pos <= left_limit: 
                return 0.0
            if pos == target: 
                return 1.0
            if pos in memo: 
                return memo[pos]
            prob = (1 - p_val[pos]) * dp(pos - 1) + p_val[pos] * dp(pos + 1)
            memo[pos] = prob
            return prob

        return p_val[l - 1] * dp(l) * p_val[l - 1]
    else:
        # General case
        left_limit = l - 2
        target = r - 1

        memo = {}
        def dp(pos):
            if pos <= left_limit: 
                return 0.0
            if pos == target: 
                return 1.0
            if pos in memo: 
                return memo[pos]
            prob = (1 - p_val[pos]) * dp(pos - 1) + p_val[pos] * dp(pos + 1)
            memo[pos] = prob
            return prob

        prob_reach = dp(l)
        return p_val[l - 1] * prob_reach * p_val[r - 1]

