            divisors.append(d)
            if d * d != S:
                divisors.append(S // d)
        d += 1
    if S > 1:
        divisors.append(S)

    min_cost = float('inf')

    # For each divisor k > 1, calculate the minimum cost
    for k in divisors:
        if k > 1:
            cost = 0
            running = 0
            for x in a:
                running += x % k
                cost += running % k
            if cost < min_cost:
                min_cost = cost

    # If we never found a valid cost (shouldn't happen for S >= 2)
    if min_cost == float('inf'):
        return "-1\n"

    return str(min_cost) + "\n"

