    for i in range(1, m + 1):
        try:
            u = int(next(iterator))
            v = int(next(iterator))
            w = int(next(iterator))
            adj[u].append((v, w, i))
            adj[v].append((u, w, i))
        except StopIteration:
            break

    try:
        start_node = int(next(iterator))
    except StopIteration:
        start_node = 1

    dist = [float('inf')] * (n + 1)
    dist[start_node] = 0

    pq = [(0, start_node)]

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist[u]:
            continue

        for v, w, idx in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    total_weight = 0
    tree_indices = []

    for v in range(1, n + 1):
        if v == start_node:
            continue

        best_w = float('inf')
        best_idx = -1

        for u, w, idx in adj[v]:
            if dist[u] != float('inf') and dist[v] == dist[u] + w:
                if w < best_w:
                    best_w = w
                    best_idx = idx

        if best_idx != -1:
            total_weight += best_w
            tree_indices.append(best_idx)

    indices_str = " ".join(map(str, tree_indices))
    if indices_str:
        indices_str += " "

    return f"{total_weight}\n{indices_str}"

