        parts = line.strip().split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)
            adj[v].append(u)

    def simulate_and_compute(start):
        """Simulate activation starting from 'start' and compute total potential."""
        activated = {start}
        order = [start]

        # BFS to find activation order
        q = collections.deque([start])
        while q:
            node = q.popleft()
            for neighbor in adj[node]:
                if neighbor not in activated:
                    activated.add(neighbor)
                    order.append(neighbor)
                    q.append(neighbor)

        total = 0
        # At each step, add the component size of currently activated nodes
        for node in order:
            # BFS among activated nodes to find component size
            component_q = collections.deque([node])
            visited = {node}
            while component_q:
                cur = component_q.popleft()
                for neighbor in adj[cur]:
                    if neighbor in activated and neighbor not in visited:
                        visited.add(neighbor)
                        component_q.append(neighbor)
            total += len(visited)

        return total

    # Find maximum over all possible starting nodes
    max_total = 0
    for start in range(N):
        total = simulate_and_compute(start)
        max_total = max(max_total, total)

    return str(max_total)

