def fibonacci_decompositions(n: int, fibs: List[int]) -> int:
    """
    Count the number of ways to decompose n into distinct Fibonacci numbers.
    This uses the property that each Fib number can be represented as the sum of
    two smaller consecutive Fib numbers.
    """
    if n <= 0:
        return 0

    # Memoization
    memo = {}

    def count_ways(nv: int, max_idx: int) -> int:
        if nv == 0:
            return 1
        if nv < 0:
            return 0
        if (nv, max_idx) in memo:
            return memo[(nv, max_idx)]

        # Find the largest Fibonacci number <= nv
        i = max_idx
        found = False

        # Work backwards to find largest Fib <= nv
        j = max_idx
        while j > 0:
            if fibs[j - 1] <= nv:
                i = j - 1
                found = True
                break
            j -= 1

        if not found or i <= 0:
            return memo[(nv, max_idx)] = 0

        # Two choices: either use fibs[i-1] or don't use it (consider smaller ones)
        ways = 0

        # Case 1: don't use fibs[i-1], use smaller Fibonacci numbers
        ways += count_ways(nv, i - 1)

        # Case 2: use fibs[i-1]
        if fibs[i - 1] <= nv:
            ways += count_ways(nv - fibs[i - 1], i - 2)

        return memo[(nv, max_idx)] = ways

    # Find index bound (largest Fibonacci with index)
    bound_idx = len(fibs) - 1

    return count_ways(n, bound_idx)

