def fibonacci_decompositions_correct(n: int, fibs: List[int]) -> int:
    """
    The number of ways to represent n as a sum of distinct Fibonacci numbers
    (where we can't use the same Fibonacci number twice) equals the number
    of ways to choose a subset of Fibonacci numbers that sum to n.

    Key insight: For a number's Zeckendorf representation F_i + F_j + ... + F_k
    where i > j > ... > k + 2 >= 1 (non-consecutive), the number of such
    decompositions is 2^(number of consecutive pairs we can form)
    """
    if n <= 0:
        return 0

    # Try smaller n values for memoization
    memo = {}

    def count(remaining: int, idx: int) -> int:
        if remaining == 0:
            return 1
        if remaining < 0 or idx < 0:
            return 0
        if (remaining, idx) in memo:
            return memo[(remaining, idx)]

        # Find largest Fibonacci with index idx that's <= remaining
        max_fib = idx
        while max_fib >= 0 and fibs[max_fib] > remaining:
            max_fib -= 1

        if max_fib < 0:
            memo[(remaining, idx)] = 0
            return 0

        # Option 1: Skip fibs[max_fib]
        res = count(remaining, max_fib - 1)

        # Option 2: Use fibs[max_fib]
        res += count(remaining - fibs[max_fib], max_fib - 2)

        memo[(remaining, idx)] = res
        return res

    return count(n, len(fibs) - 1)

