def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    s = lines[1].strip()

    # If k > n, impossible to reach |balance| == k at final step
    # Since each move changes balance by at most 1, and we start at 0
    if k > n:
        return "NO\n"

    # Use DP: reachable balances at each position
    reachable = {0}
    parent = {}  # (i, balance) -> (prev_balance, action)

    for i in range(n):
        new_reachable = set()
        current_char = s[i]

        # Determine possible actions based on character
        possible_actions = []
        if current_char == 'W' or current_char == '?':
            possible_actions.append((1, 'W'))
        if current_char == 'L' or current_char == '?':
            possible_actions.append((-1, 'L'))
        if current_char == 'D' or current_char == '?':
            possible_actions.append((0, 'D'))

        for prev_balance in list(reachable):
            for delta, action in possible_actions:
                next_balance = prev_balance + delta

                valid = False
                if i == n - 1:
                    # Last position: must reach exactly |k|
                    if abs(next_balance) == k:
                        valid = True
                else:
                    # Previous positions: must not reach |k| yet
                    if abs(next_balance) < k:
                        valid = True

                if valid:
                    # Store parent only on first visit
                    if (i, next_balance) not in parent:
                        parent[(i, next_balance)] = (prev_balance, action)
                    new_reachable.add(next_balance)

        reachable = new_reachable

    # Find any valid final balance
    final_balance = None
    for b in reachable:
        if abs(b) == k:
            final_balance = b
            break

    if final_balance is None:
        return "NO\n"

    # Backtrack to reconstruct solution
    result = []
    b = final_balance
    for i in range(n - 1, -1, -1):
        prev_b, action = parent[(i, b)]
        result.append(action)
        b = prev_b

    return ''.join(reversed(result)) + '\n'

